# Test the as_series function directly without importing numpy
import sys
sys.path.insert(0, 'numpy/numpy/polynomial')

# Mock numpy
class MockArray:
    def __init__(self, data):
        self.data = data if isinstance(data, list) else [data]
        self.size = len(self.data)
        self.ndim = 1
        self.dtype = 'float64'
        self.shape = (len(self.data),)

    def copy(self):
        return MockArray(self.data[:])

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        return self.data[idx]

class MockNP:
    def array(self, a, ndmin=None, copy=None):
        return MockArray(a)

    def common_type(self, *arrays):
        return 'float64'

# Replace the numpy import in polyutils
import importlib.util
spec = importlib.util.spec_from_file_location('polyutils', 'numpy/numpy/polynomial/polyutils.py')
polyutils = importlib.util.module_from_spec(spec)
polyutils.np = MockNP()

# Execute the module
exec(spec.loader.get_code(spec.name), polyutils.__dict__)

# Test the function
print('Configuration:', polyutils._as_series_config)
try:
    result = polyutils.as_series([[1, 2], [3, 4]])
    print('Success! as_series works')
except Exception as e:
    print('Error in as_series:', e)
    import traceback
    traceback.print_exc()
